update public.skill_test_questions
set is_active=false, updated_at=now()
where id in (
 '65a400c3-d998-4a17-a469-3bd304cfa3a1'::uuid,
 'b3ff0791-1ba1-4d45-b3f1-e677009b8337'::uuid
);

with src as (
  select *
  from jsonb_to_recordset($json$[{"id":"022324f4-0590-4e6f-af64-2ddd1a85afca","code":"P2006T-GOV-01","cat":"P2006T · Propeller and governor","topic":"Governor identity, purpose and approved description","q":"What is the propeller governor fitted to the P2006T?","a":"It is the MT-Propeller P-875-12 hydraulic governor for the MTV-21 constant-speed, fully featherable propeller. Its job is to control propeller RPM by varying blade pitch; it does not set engine power. In this installation, governor oil pressure reduces blade pitch.","f":[{"question":"Manufacturer, model and type — exactly?","expected_answer":"MT-Propeller, model P-875-12, hydraulic."},{"question":"Which propeller is it controlling?","expected_answer":"The MT-Propeller MTV-21-A-C-F/CF178-05, two-blade wood/composite, variable-pitch and fully featherable propeller."},{"question":"What variable is the governor trying to hold?","expected_answer":"Selected propeller RPM. Manifold pressure and throttle determine engine power; the governor changes pitch to maintain the selected RPM within its governing range."},{"question":"Does the governor control engine power?","expected_answer":"No. It controls propeller RPM through blade pitch. The throttle controls manifold pressure and therefore power."},{"question":"In this aeroplane, what does oil pressure do to blade pitch?","expected_answer":"The AFM states that oil pressure reduces pitch, moving the blades toward finer pitch."},{"question":"So what direction does the propeller move if governing oil pressure is lost?","expected_answer":"Toward higher pitch and ultimately feather, not toward fine pitch."},{"question":"Where does a fixed count of possible pressure-loss causes come from?","expected_answer":"Not from the AFM. The AFM gives the operating direction and consequence. An exhaustive failure-mode count requires the applicable MT-Propeller/governor maintenance data; do not invent a number."}],"k":["P-875-12 hydraulic governor","MTV-21 fully featherable propeller","Controls RPM through pitch, not engine power","Oil pressure reduces pitch","Pressure loss drives high pitch/feather"],"w":["It is an engine RPM limiter.","The governor controls manifold pressure.","Loss of oil pressure drives the blades to fine pitch.","There are exactly two failure causes because I remember that from another aircraft."],"sec":"AFM Sections 1, 2 and 7 — Propeller and governor","pg":"1-6 to 1-7; 2-10; 7-11","ord":1},{"id":"b46ef19e-3b43-43f3-b055-3793dae7f78a","code":"P2006T-GOV-03","cat":"P2006T · Propeller and governor","topic":"Governor ground check exact sequence and interpretation","q":"Show me the P2006T governor check. Give me the numbers, not a generic description.","a":"With the engine set to 1650 propeller RPM, move the propeller lever slowly to reduce propeller speed to 1200 RPM, return it full forward, repeat the cycle three times, verify that the governor controls RPM closely and firmly, and confirm restoration of 1650 RPM. Do not allow propeller speed below 1150 RPM.","f":[{"question":"How many cycles?","expected_answer":"Three."},{"question":"What drop does the AFM recommendation expect?","expected_answer":"Approximately 400 to 500 propeller RPM."},{"question":"What is the target low RPM in the checklist?","expected_answer":"1200 propeller RPM."},{"question":"What is the absolute minimum you must not cross?","expected_answer":"1150 propeller RPM."},{"question":"What must you do if the drop exceeds 500 RPM?","expected_answer":"Push the propeller lever forward to arrest the excessive drop."},{"question":"What does the check prove?","expected_answer":"Governor efficiency and positive RPM control."},{"question":"What does it not prove?","expected_answer":"It does not prove complete feathering function."},{"question":"Why must the first movement be slow and gentle?","expected_answer":"The first cycle can respond with delay. Chasing that delay may cause an abrupt excessive RPM drop, gearbox and engine wear, and in severe cases detonation."}],"k":["Start and restore 1650 prop RPM","Reduce to 1200 RPM","Never below 1150 RPM","Repeat three times","400–500 RPM drop","Checks governor efficiency, not full feathering"],"w":["Cycle it once until I see any RPM movement.","Pull it rapidly because the first response is delayed.","The purpose is to prove the propeller will feather.","An 800 RPM drop is acceptable if it recovers."],"sec":"AFM Section 4 — Normal operations and prior-to-take-off governor check","pg":"S4-3 to S4-4; S4-23","ord":2},{"id":"8853e27f-3cd3-4949-8368-0650b4c67342","code":"P2006T-PROP-01","cat":"P2006T · Propeller and governor","topic":"Propeller overspeed recognition and AFM response","q":"The propeller RPM is increasing uncontrollably. What do you do?","a":"Reduce the affected engine throttle to the minimum practical power, reduce the propeller lever as practical without selecting feather, and check RPM. If RPM cannot be reduced, secure the affected engine and land as soon as possible using the one-engine-inoperative landing procedure.","f":[{"question":"Which lever moves first?","expected_answer":"Throttle: reduce affected-engine power to the minimum practical."},{"question":"Then what do you do with the propeller lever?","expected_answer":"Reduce it as practical, but do not move it into feather as the initial overspeed action."},{"question":"Why not simply pull it straight to feather?","expected_answer":"The AFM first requires an attempt to control the overspeed with reduced power and a practical RPM selection. Feathering is part of securing the engine if RPM cannot be controlled."},{"question":"What indication confirms whether your action worked?","expected_answer":"The affected propeller RPM indication."},{"question":"What if RPM remains uncontrollable?","expected_answer":"Apply the engine-securing procedure and land as soon as possible OEI."},{"question":"What inspection consequence follows an exceedance?","expected_answer":"The propeller and engine require inspection in accordance with their applicable manuals because maximum RPM exceedance may damage engine components."},{"question":"What is the maximum propeller RPM red line in the basic applicable data?","expected_answer":"2388 propeller RPM; confirm the actual aircraft supplement and display markings."}],"k":["Throttle minimum practical","Propeller lever reduce, not initially feather","Check RPM","If uncontrollable, secure engine","Land as soon as possible","Inspection required after exceedance"],"w":["Propeller lever immediately to feather without reducing power.","Increase power to load the governor.","Continue if the RPM returns by itself.","An overspeed has no maintenance consequence if it was brief."],"sec":"AFM Section 3 — Powerplant emergencies, propeller overspeeding","pg":"S3-23; Section 2 instrument markings","ord":3},{"id":"96805325-71b3-4951-9713-d32277a226d1","code":"P2006T-ELEC-01","cat":"P2006T · Electrical system","topic":"Electrical generation architecture and exact ratings","q":"Describe the P2006T electrical generation system. How many generators, how many volts and how many amps?","a":"The applicable Sevenair P2006T configuration has two engine-driven DC generators operating in parallel during normal operation. Each is rated at 14.2 to 14.8 VDC and 40 A, with an integrated voltage regulator and automatic overvoltage protection. Secondary power is from a 12 V, 38 Ah lead-acid battery.","f":[{"question":"How do the two generators operate normally?","expected_answer":"In parallel."},{"question":"Voltage rating of each?","expected_answer":"14.2 to 14.8 VDC."},{"question":"Current rating of each?","expected_answer":"40 A."},{"question":"What maintains the output voltage?","expected_answer":"An integrated regulator on each generator."},{"question":"What protects against excessive generator voltage?","expected_answer":"An automatic overvoltage device."},{"question":"Battery specification?","expected_answer":"12 V, 38 Ah lead-acid in the cited configuration."},{"question":"Where do you read each generator's current?","expected_answer":"On the voltmeter/ammeter, selecting the left or right generator with the dedicated ammeter selector."},{"question":"Do not call it a 28-volt system — why?","expected_answer":"Because the cited aircraft generation and battery system is nominally 14/12 VDC, not 28/24 VDC."}],"k":["Two engine-driven generators","Parallel normal operation","14.2–14.8 VDC each","40 A each","Integrated regulation and overvoltage protection","12 V 38 Ah battery"],"w":["Two 28-volt alternators.","Each alternator supplies 14 amps.","One generator runs the left engine and the other runs the right engine.","The battery is the primary source in normal flight."],"sec":"Applicable S4A electrical-load analysis — DC generation","pg":"F12-14 Ed.01, pages 4–5","ord":4},{"id":"f93e72a2-b12f-425e-a191-c252dd557aaa","code":"P2006T-ELEC-03","cat":"P2006T · Electrical system","topic":"Overvoltage versus overcurrent","q":"What is the difference between overvoltage and overcurrent on the P2006T, and how would you recognise each?","a":"Overvoltage is excessive electrical potential on a bus, typically associated with a regulation or generator fault; the AFM annunciates it as L BUS VOLT HIGH or R BUS VOLT HIGH. Overcurrent is excessive amperage demanded from or supplied by a source; it is assessed on the ammeter and through applicable protection, not by calling a high-voltage annunciation 'overcurrent'. In the basic 40 A marking, 0–40 A is normal and 41–50 A is the caution range, subject to the actual aircraft supplement.","f":[{"question":"Define voltage without using the word current.","expected_answer":"Electrical potential difference — the driving pressure of the electrical system."},{"question":"Define current.","expected_answer":"The rate of electrical charge flow, measured in amperes."},{"question":"Which cockpit warning says overvoltage?","expected_answer":"L BUS VOLT HIGH or R BUS VOLT HIGH."},{"question":"Which caution says generator failure?","expected_answer":"L ALT FAIL or R ALT FAIL."},{"question":"Does ALT FAIL automatically mean overcurrent?","expected_answer":"No. It identifies generator failure; current, voltage and bus indications must be cross-checked."},{"question":"What is the rating of each generator?","expected_answer":"40 A in the applicable Sevenair electrical-load analysis."},{"question":"What is the applicable basic ammeter range?","expected_answer":"0–40 A normal and 41–50 A caution in the cited 40 A markings; verify the aircraft-specific supplement."},{"question":"Why is overvoltage dangerous?","expected_answer":"It can damage electrical and avionics equipment, which is why the generators have automatic overvoltage protection and the QRH isolates the affected field/source."}],"k":["Voltage and current are different quantities","BUS VOLT HIGH identifies overvoltage","ALT FAIL identifies generator failure","Ammeter shows source current","40 A generator rating","Check aircraft-specific markings"],"w":["Overvoltage and overcurrent are the same thing.","ALT FAIL means the battery voltage is high.","The voltmeter tells me amperage.","Any reading below 50 A is normal."],"sec":"AFM Section 2 alerts/markings and applicable electrical-load analysis","pg":"S2-12 to S2-13; F12-14 pages 4–5","ord":5},{"id":"a6b06128-915c-49d6-b8d7-da4f239a02b4","code":"P2006T-ELEC-05","cat":"P2006T · Electrical system","topic":"Both alternators failure and battery endurance","q":"Both L ALT FAIL and R ALT FAIL appear. What do you do and how much time do you have?","a":"Cycle both FIELD switches OFF then ON. If one generator recovers, verify its ammeter indication and use the single-alternator procedure. If neither recovers, set both FIELD switches OFF, both CROSS BUS switches OFF, select EMERG BATT ON if the starting-battery modification is installed, and land as soon as possible. The QRH states at least 30 minutes from a fully charged battery, but actual endurance depends on condition and load.","f":[{"question":"Why cycle both fields?","expected_answer":"To attempt restoration of the generator field/regulation circuits in the approved sequence."},{"question":"One side recovers — what proves it?","expected_answer":"A good ammeter indication and stable electrical indications on the restored side."},{"question":"Neither side recovers — field positions?","expected_answer":"Both OFF."},{"question":"Cross-bus positions?","expected_answer":"Both OFF."},{"question":"Emergency battery switch?","expected_answer":"ON if the engine-starting-battery modification is installed."},{"question":"Landing urgency?","expected_answer":"Land as soon as possible."},{"question":"Published battery endurance?","expected_answer":"At least 30 minutes with a fully charged battery."},{"question":"Is 30 minutes a fuel-like guaranteed planning figure?","expected_answer":"No. It is the published minimum under the stated condition, not permission to delay. Battery age, charge, temperature and electrical load affect actual endurance."},{"question":"What should you lose deliberately?","expected_answer":"Non-essential loads and equipment as defined by the actual bus/load table, preserving the equipment needed for control, navigation, communication and landing."}],"k":["Cycle both fields once","Use recovered generator if available","If none: fields OFF, cross buses OFF","Emergency battery if installed","At least 30 minutes stated","Land as soon as possible"],"w":["Thirty minutes means I can continue for exactly thirty minutes.","Leave both cross buses on to share battery power.","A battery voltage indication proves endurance.","Land as soon as practical, not possible."],"sec":"AFM/Sevenair QRH Section 3 — Both alternators failure","pg":"S3-8; QRH page 27","ord":6},{"id":"145d6236-ffa2-4dea-ab01-4b281cbee7da","code":"P2006T-ELEC-06","cat":"P2006T · Electrical system","topic":"Both-bus overvoltage and total electrical failure","q":"Both BUS VOLT HIGH warnings appear. Why is that more serious than a single ALT FAIL, and what is the isolation logic?","a":"Both warnings mean both electrical sides are reporting excessive bus voltage, which can damage equipment. The QRH first removes both fields and then restores them one at a time to identify a serviceable source. If the warnings persist, it isolates both cross buses and repeats controlled one-at-a-time restoration. If no safe source can be retained, both fields remain OFF, emergency battery is selected if installed, and the aircraft lands as soon as possible.","f":[{"question":"Initial field action?","expected_answer":"Both FIELD switches OFF."},{"question":"How do you restore them?","expected_answer":"One at a time, monitoring the warning and ammeter indications."},{"question":"Why one at a time?","expected_answer":"To identify which source or side recreates the overvoltage without reconnecting both suspected sources together."},{"question":"If both warnings persist with cross buses connected?","expected_answer":"Set both CROSS BUS switches OFF, both FIELD switches OFF, then attempt one-at-a-time field restoration again."},{"question":"No source can be retained safely — then what?","expected_answer":"Both fields OFF, emergency battery ON if installed, and land as soon as possible."},{"question":"What is the risk of leaving an overvoltage source connected?","expected_answer":"Damage to circuits and avionics from excessive voltage."},{"question":"Now assume total electrical failure. What flight-control consequences matter?","expected_answer":"Flaps are unavailable, normal landing-gear operation may be unavailable and emergency gear extension is required; the QRH states landing distance without flaps increases by about 25 percent."},{"question":"What battery endurance is stated?","expected_answer":"At least 30 minutes from a fully charged battery, without treating it as time to waste."}],"k":["BUS VOLT HIGH is excessive bus voltage","Fields OFF, restore one at a time","Use cross buses to isolate sides","Do not retain a source that recreates overvoltage","Emergency battery if installed","Total failure removes flaps and requires emergency gear planning"],"w":["BUS VOLT HIGH means excessive amperage.","Turn both fields back on together and leave them there.","Cross buses should always remain on during overvoltage.","Total electrical failure does not affect flap or landing-gear operation."],"sec":"Sevenair QRH — Both alternators overvoltage and total electrical failure","pg":"QRH pages 28–30","ord":7}]$json$::jsonb) as x(
    id uuid, code text, cat text, topic text, q text, a text,
    f jsonb, k text[], w text[], sec text, pg text, ord int
  )
)
